<script setup lang="ts">import {onMounted,onUnmounted,ref} from 'vue'; const data=ref<any>({projects:0,applications:0,infrastructure:{}});let source:EventSource|undefined;const load=async()=>{const r=await fetch('/api/v1/dashboard');if(r.ok)data.value=await r.json()};onMounted(async()=>{await load();source=new EventSource('/api/v1/events');source.onmessage=()=>load()});onUnmounted(()=>source?.close());</script>
<template><div class="hero"><div><p class="kicker">Thursday, July 17</p><h1>Good morning.</h1><p class="muted">Your infrastructure, at a glance.</p></div><RouterLink class="primary" to="/projects">+ New project</RouterLink></div><div class="status"><span class="dot"></span><div><strong>{{data.infrastructure?.available?'Infrastructure connected':'Infrastructure needs attention'}}</strong><p>{{data.infrastructure?.available?`Docker ${data.infrastructure.engine_version} · ${data.infrastructure.running||0} running containers`:data.infrastructure?.message||'Docker connection needs attention'}}</p></div><span class="pill">{{data.infrastructure?.available?'Healthy':'Unknown'}}</span></div><div class="grid"><article><span class="label">PROJECTS</span><strong>{{data.projects}}</strong><p class="muted">Organized environments</p></article><article><span class="label">APPLICATIONS</span><strong>{{data.applications}}</strong><p class="muted">Across all projects</p></article><article><span class="label">SWARM NODES</span><strong>{{data.infrastructure?.swarm?.nodes||'—'}}</strong><p class="muted">{{data.infrastructure?.swarm?.active?'Connected':'Not initialized'}}</p></article></div><div v-if="!data.projects" class="empty"><div class="empty-icon">⌁</div><h2>Start with a project</h2><p>Create a project to organize your applications and deployment environment.</p><RouterLink class="secondary" to="/projects">Create your first project</RouterLink></div><div v-else-if="data.activity?.length" class="project-list"><article v-for="item in data.activity" :key="item.created_at+item.action"><strong>{{item.action}}</strong><p class="muted">{{item.resource_type}} · {{new Date(item.created_at).toLocaleString()}}</p></article></div></template>
